{

"kind": "propose",
"summary": "Increase probe timeouts to match application response times",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Application responds slower than probe timeout settings",
    "supporting": ["probe_timeouts", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search-api",
    "uid": "uid-deployment-search-api"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    },
    "readiness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Prevent probe timeouts by aligning with application's actual response times",
  "rationale": "Logs show /ready and /healthz endpoints take 1.2s-1.7s to respond, but probes timeout after 1s. Increasing timeouts to 10s will allow the application to respond before probes fail.",
  "cited_evidence_ids": ["ev-container_logs_tail", "probe_timeouts", "ev-target_events"],
  "cited_predicates": ["probe_timeouts", "probe_kills"]
}
}

